import{_ as e,o,c as r,a0 as t}from"./chunks/framework.tsJrOMu2.js";const u=JSON.parse('{"title":"隐私政策","description":"","frontmatter":{"title":"隐私政策"},"headers":[],"relativePath":"privacy-policy.md","filePath":"privacy-policy.md"}'),i={name:"privacy-policy.md"};function l(n,a,s,h,d,c){return o(),r("div",null,[...a[0]||(a[0]=[t('<h1 id="隐私政策" tabindex="-1">隐私政策 <a class="header-anchor" href="#隐私政策" aria-label="Permalink to &quot;隐私政策&quot;">​</a></h1><p><strong>最后更新日期：2026 年 7 月 10 日</strong></p><p>本隐私政策适用于 leechbox.xyz（以下简称&quot;本站&quot;）。本站尊重并保护所有访问者的个人隐私。</p><h2 id="信息收集" tabindex="-1">信息收集 <a class="header-anchor" href="#信息收集" aria-label="Permalink to &quot;信息收集&quot;">​</a></h2><p>本站本身不主动收集您的个人身份信息。但以下第三方服务可能会收集匿名数据：</p><h3 id="google-adsense" tabindex="-1">Google AdSense <a class="header-anchor" href="#google-adsense" aria-label="Permalink to &quot;Google AdSense&quot;">​</a></h3><p>本站使用 Google AdSense 展示广告。Google 可能会使用 Cookie 和网络信标来根据您之前访问本站或其他网站的记录向您投放广告。您可以通过访问 <a href="https://www.google.com/settings/ads" target="_blank" rel="noreferrer">Google 广告设置</a> 停用个性化广告。</p><h3 id="不蒜子-busuanzi" tabindex="-1">不蒜子（busuanzi） <a class="header-anchor" href="#不蒜子-busuanzi" aria-label="Permalink to &quot;不蒜子（busuanzi）&quot;">​</a></h3><p>本站使用不蒜子进行匿名访问量统计，不收集任何个人身份信息。</p><h2 id="cookie-使用" tabindex="-1">Cookie 使用 <a class="header-anchor" href="#cookie-使用" aria-label="Permalink to &quot;Cookie 使用&quot;">​</a></h2><p>本站可能通过第三方服务（如 Google AdSense）使用 Cookie。Cookie 是存储在您浏览器中的小型文本文件，用于记录匿名偏好信息。</p><p>您可以在浏览器设置中禁用 Cookie，但这可能影响部分功能的正常使用。</p><h2 id="第三方链接" tabindex="-1">第三方链接 <a class="header-anchor" href="#第三方链接" aria-label="Permalink to &quot;第三方链接&quot;">​</a></h2><p>本站可能包含指向第三方网站的链接。本站对这些外部网站的隐私政策和内容不承担任何责任。</p><h2 id="儿童隐私" tabindex="-1">儿童隐私 <a class="header-anchor" href="#儿童隐私" aria-label="Permalink to &quot;儿童隐私&quot;">​</a></h2><p>本站不面向 13 岁以下儿童。我们不会故意收集儿童的个人信息。</p><h2 id="政策变更" tabindex="-1">政策变更 <a class="header-anchor" href="#政策变更" aria-label="Permalink to &quot;政策变更&quot;">​</a></h2><p>本站保留随时更新本隐私政策的权利。更新后将在本页公布最新版本。</p><h2 id="联系方式" tabindex="-1">联系方式 <a class="header-anchor" href="#联系方式" aria-label="Permalink to &quot;联系方式&quot;">​</a></h2><p>如对本隐私政策有任何疑问，请通过本站公布的社交媒体账号联系站长。</p>',20)])])}const b=e(i,[["render",l]]);export{u as __pageData,b as default};
